WebApkInstanceAsyncWaiter::WebApkInstanceAsyncWaiter(
    WebApkInstance* proxy) : proxy_(proxy) {}

WebApkInstanceAsyncWaiter::~WebApkInstanceAsyncWaiter() = default;

void WebApkInstanceAsyncWaiter::InstallWebApk(
    const std::string& package_name, uint32_t version, const std::string& app_name, const std::string& token, WebApkInstallResult* out_result) {
  base::RunLoop loop;
  proxy_->InstallWebApk(std::move(package_name),std::move(version),std::move(app_name),std::move(token),
      base::BindOnce(
          [](base::RunLoop* loop,
             WebApkInstallResult* out_result
,
             WebApkInstallResult result) {*out_result = std::move(result);
            loop->Quit();
          },
          &loop,
          out_result));
  loop.Run();
}

WebApkInstallResult WebApkInstanceAsyncWaiter::InstallWebApk(
    const std::string& package_name, uint32_t version, const std::string& app_name, const std::string& token) {
  WebApkInstallResult async_wait_result;
  InstallWebApk(std::move(package_name),std::move(version),std::move(app_name),std::move(token),&async_wait_result);
  return async_wait_result;
}

void WebApkInstanceAsyncWaiter::GetWebApkInfo(
    const std::string& package_name, WebApkInfoPtr* out_result) {
  base::RunLoop loop;
  proxy_->GetWebApkInfo(std::move(package_name),
      base::BindOnce(
          [](base::RunLoop* loop,
             WebApkInfoPtr* out_result
,
             WebApkInfoPtr result) {*out_result = std::move(result);
            loop->Quit();
          },
          &loop,
          out_result));
  loop.Run();
}

WebApkInfoPtr WebApkInstanceAsyncWaiter::GetWebApkInfo(
    const std::string& package_name) {
  WebApkInfoPtr async_wait_result;
  GetWebApkInfo(std::move(package_name),&async_wait_result);
  return async_wait_result;
}






